{"command": "python3 <<'PY'
# parse list to get lexer data
with open('/tmp/list_exact.txt') as f:
    txt=f.read()
# lexers section is from start to "styles:"
lex_part=txt.split('\nstyles:')[0]
# Count lexers: lines starting with "  " but not "    "
import re
lexers=[]
current=None
for line in lex_part.split('\n'):
    if line.startswith('  ') and not line.startswith('    '):
        name=line.strip()
        current={'name':name, 'aliases':[], 'filenames':[], 'mimetypes':[]}
        lexers.append(current)
    elif line.strip().startswith('aliases:'):
        current['aliases']=line.strip().split('aliases: ')[1].split() if 'aliases: ' in line else []
    elif line.strip().startswith('filenames:'):
        current['filenames']=line.strip().split('filenames: ')[1].split() if 'filenames: ' in line else []
    elif line.strip().startswith('mimetypes:'):
        current['mimetypes']=line.strip().split('mimetypes: ')[1].split() if 'mimetypes: ' in line else []
print(f"lexers: {len(lexers)}")
print(lexers[:2])
# check plaintext
for l in lexers:
    if l['name'].lower()=='plaintext':
        print(l)
PY"}

