import subprocess
def tok(code, fn):
    r=subprocess.run(['./executable','-s','monokai','-f','tokens','--filename',fn], input=code, capture_output=True, text=True)
    return r.stdout.strip()[:200].replace(chr(10),' | ')

# discriminating: bash echo vs plaintext
for fn in ['foo.sh','.bashrc','bashrc','foo.bash','foo.zsh','Dockerfile','Makefile','foo.py','foo.go','foo.json','foo.xml','foo.html']:
    print(fn, "=>", tok('echo hi\n', fn))
print("---")
for fn in ['Dockerfile','dockerfile','Makefile','makefile','CMakeLists.txt','foo.Dockerfile']:
    print(fn, "=>", tok('FROM alpine\n', fn))
