{"command": "python3 <<'PY'
import subprocess
def autodetect(code):
    r=subprocess.run(['./executable','-s','monokai','-f','tokens'], input=code, capture_output=True, text=True)
    return r.stdout.strip()[:400].replace(chr(10),' | ')
def explicit(code, lexer):
    r=subprocess.run(['./executable','-l',lexer,'-s','monokai','-f','tokens'], input=code, capture_output=True, text=True)
    return r.stdout.strip()[:400].replace(chr(10),' | ')

# test var x=1; with different lexers to identify which one autodetect matches
code='var x=1;\n'
print("autodetect:", autodetect(code))
for lex in ['javascript','js','typescript','java','c','cpp','go','python']:
    print(lex, ":", explicit(code, lex))

print("---shebangs---")
for sh in ['#!/bin/bash\n','#!/bin/sh\n','#!/usr/bin/bash\n','#!/bin/zsh\n','#!/usr/bin/env bash\n','#!/usr/bin/python\n','#!/usr/bin/env python\n','#!/usr/bin/perl\n']:
    print(repr(sh), "=>", autodetect(sh+'echo hi\n')[:100])
PY"}

