    low=s.lower()
    style_map={x.lower():x for x in ALL_STYLES}
    if low in style_map:
        return style_map[low]
    try:
        with open(s,'rb') as f:
            content=f.read()
    except FileNotFoundError:
        prog_error(f'open {s}: no such file or directory',1)
    except IsADirectoryError:
        prog_error(f'open {s}: is a directory',1)
    except PermissionError:
        prog_error(f'open {s}: permission denied',1)
    except OSError as e:
        prog_error(f'open {s}: {(e.strerror.lower() if e.strerror else "error")}',1)
    import xml.etree.ElementTree as ET
    try:
        text=content.decode('utf-8',errors='replace')
        root=ET.fromstring(text)
    except ET.ParseError as e:
        prog_error(f'{s}: {e}',1)
    except Exception as e:
        prog_error(f'{s}: {e}',1)
    if root.tag!='style':
        prog_error(f'{s}: expected <style> root, got <{root.tag}>',1)
    name_attr=root.get('name')
    if not name_attr:
        prog_error('missing style name attribute',1)
    entries={}
    for child in root:
        if child.tag!='entry':
            continue
        t=child.get('type')
        st=child.get('style')
        if t is None or st is None:
            continue
        entries[t]=st
    CUSTOM_STYLES[s]={'name':name_attr,'entries':entries}
    return s
