    import re as _re
    css=STYLES_CSS.get(style_name,STYLES_CSS.get(style_name.lower(),""))
    def get_bg():
        mm=_re.search(r'/\* Background \*/[^}]+\{([^}]+)\}',css)
        if not mm:
            return ""
        inner=mm.group(1).strip()
        decls=[d.strip() for d in inner.split(';') if d.strip()!='']
        props={}
        for d in decls:
            if ':' not in d:
                continue
            k,v=d.split(':',1)
            props[k.strip()]=v.strip()
        parts=[]
        for k in ['color','background-color']:
            if k in props:
                v=shorten_hex_for_inline(props[k])
                parts.append(f'{k}:{v}')
        s=';'.join(parts)
        if s!="":
            s+=';'
        return s
    body_style=get_bg()
    return f'<html>\n<body style="{body_style}">\n{frag}\n</body>\n</html>\n'

