    prefix=opts.get('html-prefix','')
    css_raw=STYLES_CSS.get(style_name,STYLES_CSS.get(style_name.lower(),""))
    if prefix:
        def repl(m):
            return f'.{prefix}{m.group(1)}'
        css_raw=re.sub(r'\.([A-Za-z0-9_-]+)',repl,css_raw)
    m=re.search(r'/\* Background \*/[^}]+\{([^}]+)\}',css_raw)
    if m:
        inner=m.group(1).strip()
        tmp=inner.replace(': ',':').replace(' :',':').replace('; ',';')
        body_css=f'body {{ {tmp}; }}\n'
    else:
        body_css=""
    def pc(name):
        return (prefix+name) if prefix else name
    full='<html>\n<style type="text/css">\n'+css_raw+body_css+'</style><body class="'+pc("bg")+'">\n'+fragment+'\n</body>\n</html>\n'
    return full

