def format_svg(tokens,code,style_name):
    import re as _re
    css=STYLES_CSS.get(style_name,STYLES_CSS.get(style_name.lower(),""))
    bg_fill="#ffffff"
    fg_fill="#000000"
    m=_re.search(r'/\* Background \*/[^}]+\{([^}]+)\}',css)
    if m:
        inner=m.group(1)
        m2=_re.search(r'background-color:\s*(#[0-9a-fA-F]+)',inner)
        if m2:
            bg_fill=m2.group(1).lower()
        for part in inner.split(';'):
            part=part.strip()
            if part.startswith('color:'):
                fg_fill=part.split(':',1)[1].strip().lower()
                break
    if code=="":
        width=0
        height=26
        body=""
    else:
        parts=code.split('\n')
        if parts and parts[-1]=="":
            parts=parts[:-1]
        maxlen=max((len(l) for l in parts),default=0)
        width=maxlen*8+8 if parts else 0
        height=26+len(parts)*17 if parts else 26
        all_lines=[]
        cur=[]
        for typ,val in tokens:
            segs=val.split('\n')
            for i,seg in enumerate(segs):
                if i>0:
                    all_lines.append((cur,True))
                    cur=[]
                if seg!="":
                    cur.append((typ,seg))
        if cur!=[]:
            all_lines.append((cur,False))
        text_elems=[]
        for idx,(ltoks,has_nl) in enumerate(all_lines):
            y=f"{(idx+1)*1.2:.6f}em"
            content_parts=[]
            for typ,txt in ltoks:
                esc=txt.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;').replace('"','&quot;').replace("'",'&#39;').replace(' ','&#160;')
                entry=get_style_entry_for_token(style_name,typ)
                fg=entry.get('color')
                if fg and fg.startswith('#'):
                    fg=fg.lower()
                    content_parts.append(f'<tspan fill="{fg}">{esc}</tspan>')
                else:
                    content_parts.append(esc)
            inner=''.join(content_parts)
            nl="\n" if has_nl else ""
            text_elems.append(f'<text x="0" y="{y}" xml:space="preserve">{inner}{nl}</text>')
        body='\n'.join(text_elems)
    # Font data: huge base64, need exact. For now use placeholder that will be replaced after extracting real font.
    # To get real font, we need to extract from binary output. Since we haven't embedded, use dummy that will cause mismatch for SVG tests.
